        List<BigDecimal> overdues = new ArrayList<>();
        List<Person> everyone = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
        Map<Long, Dues.Parts> parts = Person.parts(everyone, bySheet.values().stream().flatMap(List::stream).toList(),
                table);
        Map<Long, BigDecimal> cuts = pools.getObject().personCuts(sheetId);
        for (Person person : everyone) {
            List<Claim> theirs = bySheet.getOrDefault(person.getId(), List.of());
            BigDecimal claimed = Dues.claimed(theirs, person.leaves(), today);
            BigDecimal due = Dues.total(person::gradeOn, theirs, table, person.leaves(),
                    parts.getOrDefault(person.getId(), Dues.Parts.NONE),
                    cuts.getOrDefault(person.getId(), BigDecimal.ZERO));
            BigDecimal overdue = Dues.sum(person::gradeOn, Dues.overdue(theirs, person::gradeOn, table, person.leaves()), table);
            claimedTotal = claimedTotal.add(claimed);
            overdues.add(overdue.setScale(2, RoundingMode.HALF_UP));
            if (due != null) {
                dues.add(due.setScale(2, RoundingMode.HALF_UP));
            }
            figures.put(person.getId(), new PersonFigures(person.getName(), money(claimed),
                    due == null ? "n/a" : money(due), money(overdue)));
        }
        return new Figures(figures, new Totals(money(claimedTotal), money(trimmedSum(dues)), money(trimmedSum(overdues))));
    }

    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
    private static BigDecimal trimmedSum(List<BigDecimal> figures) {
        BigDecimal sum = figures.stream().reduce(BigDecimal.ZERO, BigDecimal::add);
        if (figures.size() < 3) {
            return sum;
        }
        return sum.subtract(figures.stream().max(BigDecimal::compareTo).orElseThrow())
                .subtract(figures.stream().min(BigDecimal::compareTo).orElseThrow());
    }

    /**
     * Announce the figures the change moved since {@code before}: each person whose figures changed (one
     * who did not exist before counting as changed), then the totals when they changed, then each person whose
     * due-total went from at or below the alert threshold (or none) to above it. Nothing when no figure moved.
     */
    public void changed(String sheetId, String user, Figures before) {
        Figures after = figures(sheetId);
        List<PersonFigures> moved = new ArrayList<>();
        after.people().forEach((id, now) -> {
            if (!now.sameFigures(before.people().get(id))) {
                moved.add(now);
            }
        });
        Totals totals = Objects.equals(before.totals(), after.totals()) ? null : after.totals();
        BigDecimal threshold = new DatedSettings(settings.findBySheetId(sheetId)).alertThreshold();
        List<PersonFigures> alerts = new ArrayList<>();
        if (threshold != null) {
            after.people().forEach((id, now) -> {
                PersonFigures was = before.people().get(id);
                if (above(now, threshold) && (was == null || !above(was, threshold))) {
                    alerts.add(now);
                }
            });
        }
        if (!moved.isEmpty() || totals != null) {
            events.publishEvent(new RollupChanged(sheetId, user, moved, totals, alerts));
        }
    }

    /** Whether the person's due-total is above the threshold; never when they have none. */
    private static boolean above(PersonFigures figures, BigDecimal threshold) {
        return !"n/a".equals(figures.dueTotal()) && new BigDecimal(figures.dueTotal()).compareTo(threshold) > 0;
    }

    private static String money(BigDecimal amount) {
        return amount.setScale(2, RoundingMode.HALF_UP).toPlainString();
    }
}
